package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// 阈值配置在仓库根的 config/thresholds.json。
// go test 的工作目录是包目录，所以这里用 ../config/thresholds.json。
const thresholdsFile = "../config/thresholds.json"

// withThresholds 临时写入阈值配置，测试结束恢复原状。
func withThresholds(t *testing.T, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(thresholdsFile), 0o755); err != nil {
		t.Fatalf("创建 config 目录失败: %v", err)
	}
	original, existed := readThresholdsIfExists(t)
	if err := os.WriteFile(thresholdsFile, []byte(content), 0o644); err != nil {
		t.Fatalf("写入阈值配置失败: %v", err)
	}
	t.Cleanup(func() {
		if existed {
			if err := os.WriteFile(thresholdsFile, original, 0o644); err != nil {
				t.Errorf("恢复阈值配置失败: %v", err)
			}
			return
		}
		if err := os.Remove(thresholdsFile); err != nil && !os.IsNotExist(err) {
			t.Errorf("删除阈值配置失败: %v", err)
		}
	})
}

// withoutThresholds 确保测试期间不存在阈值配置文件，结束后恢复原状。
func withoutThresholds(t *testing.T) {
	t.Helper()
	original, existed := readThresholdsIfExists(t)
	if err := os.Remove(thresholdsFile); err != nil && !os.IsNotExist(err) {
		t.Fatalf("删除阈值配置失败: %v", err)
	}
	t.Cleanup(func() {
		if existed {
			if err := os.WriteFile(thresholdsFile, original, 0o644); err != nil {
				t.Errorf("恢复阈值配置失败: %v", err)
			}
		}
	})
}

func readThresholdsIfExists(t *testing.T) ([]byte, bool) {
	t.Helper()
	data, err := os.ReadFile(thresholdsFile)
	if os.IsNotExist(err) {
		return nil, false
	}
	if err != nil {
		t.Fatalf("读取阈值配置失败: %v", err)
	}
	return data, true
}

func TestConfiguredThresholdIsUsed(t *testing.T) {
	withThresholds(t, `{"xian": 2}`)
	if got := LowStockThreshold("xian"); got != 2 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置值 2", got)
	}
}

func TestConfiguredZeroThresholdIsUsed(t *testing.T) {
	withThresholds(t, `{"xian": 0}`)
	if got := LowStockThreshold("xian"); got != 0 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置值 0", got)
	}
}

func TestConfiguredThresholdDrivesIsLowStock(t *testing.T) {
	withThresholds(t, `{"xian": 10}`)
	if !IsLowStock("xian", 9) {
		t.Fatal("9 低于配置阈值 10，应当算低库存")
	}
	if IsLowStock("xian", 10) {
		t.Fatal("等于配置阈值不算低库存（严格小于）")
	}
}

func TestWarehouseMissingFromConfigFallsBack(t *testing.T) {
	withThresholds(t, `{"xian": 2}`)
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMissingConfigFileFallsBack(t *testing.T) {
	withoutThresholds(t)
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置不存在时应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMalformedConfigFallsBack(t *testing.T) {
	withThresholds(t, `{not json`)
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置不是合法 JSON 时应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestNonObjectConfigFallsBack(t *testing.T) {
	for _, content := range []string{`[1, 2, 3]`, `42`, `"xian"`, `null`} {
		withThresholds(t, content)
		if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
			t.Fatalf("配置 %s 不是 JSON 对象时应回退默认值 %d，得到 %d",
				content, DefaultLowStockThreshold, got)
		}
	}
}

