// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strconv"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsConfigPaths 返回阈值配置 config/thresholds.json 的候选路径。
//
// go test 的工作目录是包目录（inventory/），所以除了当前工作目录，还要从它
// 向上找到仓库根（含 go.mod 的目录）再拼出配置路径。
func thresholdsConfigPaths() []string {
	cwd, err := os.Getwd()
	if err != nil {
		return []string{filepath.Join("config", "thresholds.json")}
	}
	paths := []string{filepath.Join(cwd, "config", "thresholds.json")}
	for dir := cwd; ; {
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		if _, err := os.Stat(filepath.Join(parent, "go.mod")); err == nil {
			root := filepath.Join(parent, "config", "thresholds.json")
			if root != paths[0] {
				paths = append(paths, root)
			}
			break
		}
		dir = parent
	}
	return paths
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值从 config/thresholds.json 读取；该仓库未配置，或文件不存在、读不出来、
// 内容不是 JSON 对象时，回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	for _, path := range thresholdsConfigPaths() {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		var thresholds map[string]int
		if err := json.Unmarshal(data, &thresholds); err != nil {
			return DefaultLowStockThreshold
		}
		if threshold, ok := thresholds[warehouse]; ok {
			return threshold
		}
		return DefaultLowStockThreshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按数量升序，
// 数量相同时按仓库名升序。
func LowStockWarehouses(stock map[string]int) []string {
	type entry struct {
		warehouse string
		quantity  int
	}
	low := make([]entry, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, entry{warehouse: warehouse, quantity: quantity})
		}
	}
	sort.Slice(low, func(i, j int) bool {
		if low[i].quantity != low[j].quantity {
			return low[i].quantity < low[j].quantity
		}
		return low[i].warehouse < low[j].warehouse
	})
	warehouses := make([]string, len(low))
	for i, e := range low {
		warehouses[i] = e.warehouse
	}
	return warehouses
}

// LowStockReport 返回 stock 里低库存仓库的报告，每条形如 "<仓库>=<数量>"，
// 顺序与 LowStockWarehouses 一致。
func LowStockReport(stock map[string]int) []string {
	warehouses := LowStockWarehouses(stock)
	report := make([]string, len(warehouses))
	for i, warehouse := range warehouses {
		report[i] = warehouse + "=" + strconv.Itoa(stock[warehouse])
	}
	return report
}
